    ''' Saves data to the direcotry speficied '''
    helpers.ensuredir(dpath)
    fpath = __args2_fpath(dpath, fname, uid, ext)
    if verbose:
        if verbose > 1:
            print('[io]')
        print(('[io] smart_save(dpath=%r,\n' + (' ' * 11) + 'fname=%r, uid=%r, ext=%r)')
              % (dpath, fname, uid, ext))
    ret = __smart_save(data, fpath, verbose)
    if verbose > 1:
        print('[io]')
    return ret


