# skip-list maps
class SLView:
  def __init__(self,sl):
    self.sl=sl

  @staticmethod
  def findNextGLEB(n, level, k):
    while (not(n==None)):
      sn=n.next[level]
      if (sn==None or k < sn.key):
        if (level==0):
          return n
        else:
          level=level-1
      elif (sn.key <= k):
        n = sn
      else:
        return n

  def __getitem__(self,k):
    if (self.sl.count==0):
      return None
    else:
      n = SLView.findNextGLEB(self.sl.root, len(self.sl.root.next)-1, k)
      if (not(n == None) and n.key==k):
        return n.value
      else:
        return None
  def __contains__(self,k):
    if (self.sl.count==0):
      return False
    else:
      n=SLView.findNextGLEB(self.sl.root, len(self.sl.root.next)-1, k)
      return (not(n==None) and n.key==k)
  def __iter__(self):
    n=self.sl.root.next[0]
    while (not(n==None)):
      yield (n.key,n.value)
      n=n.next[0]
  def __len__(self): return self.sl.count
  def __str__(self): return self.__repr__()
  def __repr__(self):
    ks=[]
    eqs=[]
    vs=[]
    n=self.sl.root().next[0]
    while (not(n == None)):
      ks.append(str(n.key))
      eqs.append(' = ')
      vs.append(str(n.value))
      n=n.next[0]
    return tableFormat([ks,eqs,vs])

@RegReader("slmap")
class SLMapReader:
  def __init__(self,renv,ty,repty):
    self.sr = makeReader(renv, repty)
  def read(self,m,offset):
    return SLView(self.sr.read(m,offset))

