class HobUUID(uuid.UUID):
  def __init__(self, *args, **kwargs):
    uuid.UUID.__init__(self, *args, **kwargs)
  def __str__(self):
    return base64.b64encode(self.bytes, '-_')[:-2] + 'A'

  @staticmethod
  def bytes2uuid(bs):
    return HobUUID(bytes=''.join(chr(e) for e in bs))

