# Stored sequences (fseq T n) with representation (^x.(()+((carray T n) * x@?)))@?
#
#######
class RecStream:
  def __init__(self, stream):
    self.nodes = []
    self._reload(stream)

  def _reload(self, stream):
    self.data = stream
    def generate_node(s):
      if s[0]:
        self.nodes.append(s[0])
      if s[1] != None:
        generate_node(s[1])
    generate_node(stream)

  def iter(self):
    for nd in self.nodes:
      for v in nd():
        yield v

  def __len__(self):
    return sum((len(x) for x in self.nodes))

  def __str__(self):
    sz = 0
    content = ""
    for v in self.iter():
      sz += 1
      if sz > 10:
        content += "... ... ..."
        break
      content += "{}. {}\n".format(sz, v)
    return content

  def __getitem__(self, i):
    c = 0
    for nd in self.nodes:
      if i >= (c + len(nd)):
        c += len(nd)
      else:
        return nd[i-c]

    raise StopIteration

@RegReader("fseq")
class FSeqReader:
  def __init__(self, renv, repty, ty):
    self.rr = makeReader(renv, ty)
  def read(self, m, o):
    return RecStream(self.rr.read(m,o))

